<?php
declare(strict_types=1);
namespace WexaShelf;
final class GrowthSite
{
    private static function routes(string$locale):array{$pack=Localization::server($locale)['routes']??[];$out=[];foreach(['growthIntent'=>'intent','growthComparison'=>'comparison','growthComparisonIndex'=>'comparison','growthAlternatives'=>'alternatives','growthAuthor'=>'author','growthTest'=>'test']as$key=>$kind)if(isset($pack[$key]))$out[$pack[$key]]=$kind;return$out;}
    private static function e(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private static function json(mixed$v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);}
    public static function matches(string$path):bool{$p=explode('/',trim($path,'/'));return isset(self::routes($p[0]??'')[$p[1]??''])&&count($p)<=3&&!(($p[1]??'')===(Localization::server($p[0]??'')['routes']['karsilastir']??null)&&count($p)===2);}
    public static function sitemapEntries(array$documents,array$config,array$rules=[]):array{$out=[];$blocked=array_column($rules,'from');foreach($documents as$d)if(Growth::approved($d)&&!in_array(Growth::path($d),$blocked,true))$out[]=['url'=>Config::url($config,Growth::path($d)),'updatedAt'=>$d['updatedAt']];return$out;}
    private static function find(array$docs,string$id,string$locale):?array{foreach($docs as$d)if($d['id']===$id&&$d['locale']===$locale)return$d;return null;}
    private static function appUrl(array$catalog,array$config,string$id,string$locale):?string{
        $t=Localization::entry($catalog,'app',$id,$locale);return$t?Localization::url($config,$locale,'uygulama',$t['slug']):null;
    }
    public static function render(array$documents,array$catalog,array$config,string$path,array$query=[]):void{
        $p=explode('/',trim($path,'/'));$locale=$p[0]??'en';$t=fn(string$key)=>Localization::t($locale,$key);$kind=self::routes($locale)[$p[1]??'']??null;$slug=$p[2]??null;$doc=null;
        if(!$kind||!Localization::enabled($config,$locale)){self::missing($locale);return;}
        foreach($documents as$d)if($d['locale']===$locale&&$d['kind']===$kind&&$d['slug']===$slug)$doc=$d;
        if($slug!==null&&!$doc){self::missing($locale);return;}
        $labels=['intent'=>$t('growthIntent'),'comparison'=>$t('growthComparison'),'alternatives'=>$t('growthAlternatives'),'author'=>$t('growthAuthor'),'test'=>$t('growthTest')];
        $site=$config['seo']['siteName']??'WexaShelf';$title=$doc['title']??$labels[$kind];$description=$doc['summary']??$t('growthDescription');
        $enabled=($config['seo']['indexingEnabled']??$config['site']['indexing']??false)===true&&SEOSettings::publicHttps($config['site']['url']);$index=$enabled&&!$query&&$doc&&Growth::approved($doc);$canonical=!$query?Config::url($config,$doc?Growth::path($doc):rtrim($path,'/')):null;$alternates=[];$navigation=[];
        if($doc)foreach($documents as$other)if($other['id']===$doc['id']&&$other['kind']===$kind&&Localization::enabled($config,$other['locale'])){$link=['locale'=>$other['locale'],'href'=>Config::url($config,Growth::path($other))];$navigation[]=$link;if(!$query&&Growth::approved($doc)&&Growth::approved($other))$alternates[]=$link;}
        $robots=($index?'index':'noindex').', '.($enabled?'follow':'nofollow');header('Content-Type: text/html; charset=utf-8');header('Content-Language: '.$locale);header('X-Robots-Tag: '.$robots);$base=Config::basePath($config);
        $metaTitle=trim($doc['seo']['title']??'')?:$title;$metaDescription=trim($doc['seo']['description']??'')?:$description;
        echo'<!doctype html><html lang="'.$locale.'" dir="'.self::e(Localization::language($locale)['direction']).'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($metaTitle.' | '.$site).'</title><meta name="description" content="'.self::e($metaDescription).'"><meta name="robots" content="'.$robots.'"><link rel="stylesheet" href="'.self::e($base.'/assets/app.css').'"><link rel="icon" href="'.self::e($base.'/assets/favicon.svg').'">';
        if($canonical)echo'<link rel="canonical" href="'.self::e($canonical).'">';if(count($alternates)>1)foreach($alternates as$a)echo'<link rel="alternate" hreflang="'.$a['locale'].'" href="'.self::e($a['href']).'">';
        foreach(['og:title'=>$metaTitle,'og:description'=>$metaDescription,'og:site_name'=>$site,'og:locale'=>Localization::language($locale)['og'],'og:type'=>$doc&&$kind!=='author'?'article':'website']as$key=>$value)echo'<meta property="'.$key.'" content="'.self::e($value).'">';if($canonical)echo'<meta property="og:url" content="'.self::e($canonical).'">';
        if($canonical){$home=Localization::url($config,$locale);$pageId=$canonical.'#webpage';$graph=[['@type'=>'WebSite','@id'=>$home.'#website','name'=>$site,'url'=>$home,'inLanguage'=>$locale],['@type'=>'WebPage','@id'=>$pageId,'url'=>$canonical,'name'=>$title,'description'=>$description,'inLanguage'=>$locale,'isPartOf'=>['@id'=>$home.'#website'],'breadcrumb'=>['@id'=>$canonical.'#breadcrumb']],['@type'=>'BreadcrumbList','@id'=>$canonical.'#breadcrumb','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>$site,'item'=>$home],['@type'=>'ListItem','position'=>2,'name'=>$labels[$kind],'item'=>Config::url($config,'/'.$locale.'/'.($kind==='comparison'?Localization::server($locale)['routes']['growthComparisonIndex']:$p[1]))],['@type'=>'ListItem','position'=>3,'name'=>$title,'item'=>$canonical]]]];
            if($kind!=='author'){$article=['@type'=>'Article','@id'=>$canonical.'#article','headline'=>$title,'description'=>$description,'dateModified'=>$doc['updatedAt'],'inLanguage'=>$locale,'mainEntityOfPage'=>['@id'=>$pageId],'citation'=>array_column($doc['sources'],'url')];$author=self::find($documents,$doc['authorId'],$locale);if($author)$article['author']=['name'=>$author['title'],'url'=>Config::url($config,Growth::path($author))];$graph[]=$article;$graph[1]['mainEntity']=['@id'=>$article['@id']];}echo'<script type="application/ld+json">'.self::json(['@context'=>'https://schema.org','@graph'=>$graph]).'</script>';
        }
        echo'</head><body><div '.ThemeView::attributes($catalog,$kind).'><a class="skip-link" href="#main-content">'.self::e($t('skipToContent')).'</a><header class="site-header">'.Branding::link($config,Localization::url($config,$locale)).'<nav aria-label="'.self::e($t('editorialNavigation')).'">';
        foreach(self::routes($locale)as$segment=>$navKind)if(!($navKind==='comparison'&&$segment===Localization::server($locale)['routes']['growthComparison']))echo'<a href="'.self::e(Config::url($config,'/'.$locale.'/'.$segment)).'">'.self::e($labels[$navKind]).'</a> ';foreach($navigation as$a)echo'<a hreflang="'.$a['locale'].'" href="'.self::e($a['href']).'">'.self::e(Localization::language($a['locale'])['label']).'</a> ';
        echo'</nav></header><main id="main-content" class="content-shell"><article class="editorial-article"><header><h1>'.self::e($title).'</h1><p>'.self::e($description).'</p></header>';
        if(!$doc){$count=0;foreach($documents as$d)if($d['kind']===$kind&&$d['locale']===$locale){$count++;echo'<section><h2><a href="'.self::e(Config::url($config,Growth::path($d))).'">'.self::e($d['title']).'</a></h2><p>'.self::e($d['summary']).'</p></section>';}if(!$count)echo'<p>'.self::e($t('noPublishedResources')).'</p>';}
        else{
            if(!empty($doc['stale']))echo'<p role="status">'.self::e($t('staleGrowth')).'</p>';
            $author=self::find($documents,$doc['authorId'],$locale);if($author)echo'<p>'.self::e(($t('by').': ')).'<a href="'.self::e(Config::url($config,Growth::path($author))).'">'.self::e($author['title']).'</a></p>';
            echo'<p>'.self::e(($t('updated').': ')).self::e($doc['updatedAt']).'</p>';foreach($doc['sections']as$section){echo'<section><h2>'.self::e($section['heading']).'</h2>';foreach($section['paragraphs']as$paragraph)echo'<p>'.self::e($paragraph).'</p>';echo'</section>';}
            if($doc['test']){echo'<section><h2>'.self::e($t('recordedTest')).'</h2><dl>';foreach($doc['test']as$key=>$value){$label=$t($key);echo'<dt>'.self::e($label).'</dt><dd>'.self::e($value).'</dd>';}echo'</dl></section>';}
            if($doc['appIds']){echo'<section><h2>'.self::e($t('relatedApps')).'</h2><ul>';foreach($doc['appIds']as$id){$url=self::appUrl($catalog,$config,$id,$locale);$app=Localization::entry($catalog,'app',$id,$locale)['data']??null;if($url&&$app)echo'<li><a href="'.self::e($url).'">'.self::e($app['name']).'</a></li>';}echo'</ul></section>';}
            if($doc['links']){echo'<section><h2>'.self::e($t('readNext')).'</h2><ul>';foreach($doc['links']as$link){$target=$link['kind']==='growth'?self::find($documents,$link['id'],$locale):null;$url=$target?Config::url($config,Growth::path($target)):($link['kind']==='app'?self::appUrl($catalog,$config,$link['id'],$locale):null);if($url)echo'<li><a href="'.self::e($url).'">'.self::e($link['label']).'</a></li>';}echo'</ul></section>';}
            echo'<section><h2>'.self::e($t('sourcesAndChecks')).'</h2><ul>';foreach($doc['sources']as$s)echo'<li><a rel="noopener noreferrer" href="'.self::e($s['url']).'">'.self::e($s['title']).'</a> · '.self::e($s['checkedAt']).'</li>';echo'</ul></section>';
        }
        echo'</article></main><footer class="site-footer">'.Branding::link($config,Localization::url($config,$locale)).'<a href="'.self::e(Localization::url($config,$locale,'yontem')).'">'.self::e($t('methodology')).'</a> · <a href="'.self::e(Localization::url($config,$locale,'duzeltme-politikasi')).'">'.self::e($t('reportCorrection')).'</a></footer></div><script type="application/json" id="wexa-growth-state">'.self::json(['serverOnly'=>true,'locale'=>$locale,'documentId'=>$doc['id']??null]).'</script>'.Performance::script($catalog,$config,$path).'</body></html>';
    }
    private static function missing(string$locale):void{http_response_code(404);header('Content-Type: text/html; charset=utf-8');header('X-Robots-Tag: noindex, nofollow');echo'<!doctype html><html lang="'.self::e($locale).'"><meta charset="utf-8"><title>404</title><h1>'.self::e(Localization::complete($locale)?Localization::t($locale,'pageNotFound'):'404').'</h1></html>';}
}
